result.originalGoal:
READ-ONLY native playtest correction. NO tools/edits/game writes. Return JSON {verdict:"approve|request_changes|uncertain",findings:[],limitations:[]}. Previous member undo DID remove all66 in fresh authoritative snapshot, but synchronous IsValid/IsActorBeingDestroyed still said66remaining because native destruction is deferred. Exact SDK FGBuildable.h public GetIsDismantled() is immediate native dismantle state. Add predicate to accounting and refund helper so marked actors cannot refund twice. World capture remains final proof. Also explicit coordinates WITH z AND wording "at exact height" use EXISTING snap_to_ground:false teleport; defaults unchanged. Needed to inspect inside tunnel instead of ground-snapping onto roof. Three routing tests/full1336pass; matching Shipping rebuilt. Review concrete bugs in this diff:
diff --git a/Source/AIFactoryCopilot/Private/AIFactoryActions.cpp b/Source/AIFactoryCopilot/Private/AIFactoryActions.cpp
index db17deb..aefba04 100644
--- a/Source/AIFactoryCopilot/Private/AIFactoryActions.cpp
+++ b/Source/AIFactoryCopilot/Private/AIFactoryActions.cpp
@@ -169,2 +169,10 @@ namespace

+    bool IsActionBuildableRemoved(AFGBuildable* Buildable)
+    {
+        // Native dismantling marks this immediately but may defer destroying
+        // the actor until a later frame. Do not refund a marked actor twice.
+        return !IsValid(Buildable) || Buildable->IsActorBeingDestroyed() ||
+            Buildable->GetIsDismantled();
+    }
+
     FAIFactoryRefundDelivery DismantleWithRefund(
@@ -174,2 +182,7 @@ namespace
         FAIFactoryRefundDelivery Delivery;
+        if (AFGBuildable* Buildable = Cast<AFGBuildable>(DismantleActor);
+            Buildable && IsActionBuildableRemoved(Buildable))
+        {
+            return Delivery;
+        }
         if (!IsValid(DismantleActor) ||
@@ -397,3 +410,3 @@ namespace
             {
-                if (IsValid(Member) && !Member->IsActorBeingDestroyed())
+                if (!IsActionBuildableRemoved(Member))
                 {
@@ -453,3 +466,3 @@ namespace
                 if (AFGBuildable* Buildable = Weak.Get();
-                    IsValid(Buildable) && !Buildable->IsActorBeingDestroyed())
+                    !IsActionBuildableRemoved(Buildable))
                 {
@@ -4012,3 +4025,3 @@ FAIFactoryActionResult UndoLast(const FAIFactoryActionContext& Context)
         AFGBuildable* Buildable = Weak.Get();
-        if (!IsValid(Buildable) || Buildable->IsActorBeingDestroyed())
+        if (IsActionBuildableRemoved(Buildable))
         {
@@ -4048,3 +4061,3 @@ FAIFactoryActionResult UndoLast(const FAIFactoryActionContext& Context)
     {
-        if (!IsValid(Buildable) || Buildable->IsActorBeingDestroyed())
+        if (IsActionBuildableRemoved(Buildable))
         {
@@ -4081,3 +4094,3 @@ FAIFactoryActionResult UndoLast(const FAIFactoryActionContext& Context)
     {
-        if (!IsValid(Temporary) || Temporary->IsActorBeingDestroyed())
+        if (IsActionBuildableRemoved(Temporary))
         {
@@ -4099,3 +4112,3 @@ FAIFactoryActionResult UndoLast(const FAIFactoryActionContext& Context)
         const FString& Path = OriginalPaths.FindChecked(Buildable);
-        if (!IsValid(Buildable) || Buildable->IsActorBeingDestroyed())
+        if (IsActionBuildableRemoved(Buildable))
         {
diff --git a/companion/lib/router.mjs b/companion/lib/router.mjs
index 4180d63..c1fa24c 100644
--- a/companion/lib/router.mjs
+++ b/companion/lib/router.mjs
@@ -5536,5 +5536,5 @@ export function answerLocally(question, graph, services) {
         // Without a stated Z the numbers are a map reference, not a height.
-        // Snapping is on either way: the validator warns that turning it off
-        // drops the player through the world, and nobody asking this wants that.
-        snap_to_ground: true,
+        // Interior playtesting needs an explicit supplied height. Keep legacy
+        // snapping unless the caller also explicitly requests exact height.
+        snap_to_ground: !(teleport.had_z && /\bat exact height\b/i.test(question)),
         commit: true,
@@ -5545,3 +5545,4 @@ export function answerLocally(question, graph, services) {
             (teleport.had_z ? `, z=${round(teleport.target.z)}` : "") + "`" +
-            (teleport.had_z ? "" : " — no height given, so you land on the ground there") +
+            (!action.snap_to_ground ? " at the exact requested height" :
+              teleport.had_z ? " with ground snapping" : " — no height given, so you land on the ground there") +
             ". The mod reports where you actually arrive.",

